CREATE OR REPLACE FUNCTION public.create_notification(p_user_id uuid, p_type text, p_actor_id uuid DEFAULT NULL::uuid, p_target_type text DEFAULT NULL::text, p_target_id uuid DEFAULT NULL::uuid, p_message text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_notification_id UUID;
    v_actor_name TEXT;
    v_final_message TEXT;
BEGIN
    -- Don't notify yourself
    IF p_user_id = p_actor_id THEN
        RETURN NULL;
    END IF;

    -- Get actor name for auto-generating messages
    IF p_actor_id IS NOT NULL AND p_message IS NULL THEN
        SELECT full_name INTO v_actor_name
        FROM profiles
        WHERE id = p_actor_id;
    END IF;

    -- Auto-generate message if not provided
    IF p_message IS NOT NULL THEN
        v_final_message := p_message;
    ELSE
        CASE p_type
            WHEN 'friend_request' THEN
                v_final_message := COALESCE(v_actor_name, 'Someone') || ' sent you a friend request';
            WHEN 'friend_accepted' THEN
                v_final_message := COALESCE(v_actor_name, 'Someone') || ' accepted your friend request';
            WHEN 'badge_earned' THEN
                v_final_message := 'You earned a new badge!';
            WHEN 'content_upvoted' THEN
                v_final_message := COALESCE(v_actor_name, 'Someone') || ' upvoted your ' || COALESCE(p_target_type, 'content');
            WHEN 'welcome' THEN
                v_final_message := 'Welcome to Recall! Start by exploring flashcards.';
            ELSE
                v_final_message := 'You have a new notification';
        END CASE;
    END IF;

    -- Insert notification
    INSERT INTO notifications (
        user_id,
        type,
        actor_id,
        target_type,
        target_id,
        message,
        is_read,
        created_at
    )
    VALUES (
        p_user_id,
        p_type,
        p_actor_id,
        p_target_type,
        p_target_id,
        v_final_message,
        false,
        NOW()
    )
    RETURNING id INTO v_notification_id;

    RETURN v_notification_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_review_activity(p_user_id uuid, p_review_timestamp timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
    v_user_tz TEXT;
    v_local_timestamp TIMESTAMPTZ;
    v_activity_date DATE;
    v_activity_hour INTEGER;
BEGIN
    -- Get user's stored timezone (fallback to UTC if not set)
    SELECT COALESCE(timezone, 'UTC') INTO v_user_tz
    FROM profiles
    WHERE id = p_user_id;

    -- Convert UTC timestamp to user's local timezone
    v_local_timestamp := p_review_timestamp AT TIME ZONE v_user_tz;
    
    -- Extract local date and hour
    v_activity_date := v_local_timestamp::DATE;
    v_activity_hour := EXTRACT(HOUR FROM v_local_timestamp)::INTEGER;

    -- Insert or update activity log
    INSERT INTO user_activity_log (user_id, activity_type, activity_date, activity_hour)
    VALUES (p_user_id, 'review', v_activity_date, v_activity_hour)
    ON CONFLICT (user_id, activity_type, activity_date) 
    DO UPDATE SET activity_hour = EXCLUDED.activity_hour;

END;
$function$

CREATE OR REPLACE FUNCTION realtime.send(payload jsonb, event text, topic text, private boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
DECLARE
  generated_id uuid;
  final_payload jsonb;
BEGIN
  BEGIN
    generated_id := gen_random_uuid();

    -- Check if payload has an 'id' key, if not, add the generated UUID
    IF payload ? 'id' THEN
      final_payload := payload;
    ELSE
      final_payload := jsonb_set(payload, '{id}', to_jsonb(generated_id));
    END IF;

    -- Set the topic configuration
    EXECUTE format('SET LOCAL realtime.topic TO %L', topic);

    INSERT INTO realtime.messages (id, payload, event, topic, private, extension)
    VALUES (generated_id, final_payload, event, topic, private, 'broadcast');
  EXCEPTION
    WHEN OTHERS THEN
      RAISE WARNING 'WarnSendingBroadcastMessage: %', SQLERRM;
  END;
END;
$function$
